    'shutdown.priorityHelp':           'How groups & priorities work',
    'shutdown.priorityTip':            'GROUP PRIORITY (lower = earlier): groups sharing the same value run in PARALLEL. By default all groups are at priority 100 → everything runs in parallel between groups. INTRA-GROUP ORDER (VM #N): in a named group, VMs stop one at a time, lowest #N first. The "default" group is special: all its VMs stop in PARALLEL, no intra order.',
    'shutdown.groupsIntro':            'Two priority levels: GROUP PRIORITY (lower = earlier; same value = groups in parallel) and INTRA-GROUP ORDER (VM #N inside a named group = sequential, lowest first). The "default" group ignores intra order — all its VMs stop in parallel.',
    'shutdown.dragVmTip':              'Drag inside the group to reorder (#N changes). Drag to another group to reassign.',
    'shutdown.dragVmDefaultTip':       'In the "default" group VMs all stop in parallel — order does not matter. Drag to another group to reassign.',
    'shutdown.groupTip':               'NAMED group: VMs in this group stop sequentially (top of list = stopped first). The group runs at the priority shown; groups sharing the same priority run in parallel.',
    'shutdown.defaultGroupTip':        'DEFAULT group (catch-all): VMs without an explicit group land here. ALL its VMs stop in PARALLEL — no intra-group order. Cannot be renamed or deleted (can be empty).',
    'shutdown.defaultLockedTip':       'The "default" group cannot be renamed (it is the catch-all for VMs without explicit assignment).',
    'shutdown.groupNameTip':           'Free-form name. Must be unique and non-empty.',
    'shutdown.groupNameRequired':      'Every group (except "default") needs a name before save.',
    'shutdown.groupPriorityTip':       'Group priority. LOWER = stops earlier. Groups sharing the same value run in PARALLEL. Default 100 for all → fully parallel between groups.',
    'shutdown.groupPriorityLabel':     'priority',
    'shutdown.tierTip':                'Tier {n}: groups in this tier run in parallel. Color helps spot shared priorities at a glance.',
    'shutdown.intraPriorityTip':       'Order within the group (LOWER = stops earlier). Drag the row up/down to renumber.',
